-- R6 validation fixture g: no correlated sample at all
-- Ground truth: Sydney history via a since-removed role override; no booking has a proposal notification
-- Current state left behind: server default UTC; override RESET, so step 1 shows UTC and no overrides
-- Generated by run_r6_fixtures.py; load with psql (-v ON_ERROR_STOP=1) on schema.sql.
-- A timestamptz literal assigned to a `timestamp` column is converted in the session
-- TimeZone, exactly like the columns' DEFAULT now() at that instant.

DO $$BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'fx_api') THEN CREATE ROLE fx_api LOGIN; END IF; END$$;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO fx_api;
ALTER ROLE fx_api IN DATABASE r6_g SET timezone = 'Australia/Sydney';
\connect - fx_api
RESET TIME ZONE;
DO $$BEGIN IF current_setting('TimeZone') <> 'Australia/Sydney' THEN RAISE EXCEPTION 'writer zone is %', current_setting('TimeZone'); END IF; END$$;  -- writer: role fx_api, session TimeZone Australia/Sydney
\connect - postgres
RESET TIME ZONE;
DO $$BEGIN IF current_setting('TimeZone') <> 'UTC' THEN RAISE EXCEPTION 'writer zone is %', current_setting('TimeZone'); END IF; END$$;  -- writer: role postgres, session TimeZone UTC
ALTER ROLE fx_api IN DATABASE r6_g RESET timezone;
